INSERT INTO club_content(kind,title,body,category,active,published_at) VALUES
('wiki','Как подать заявку на аренду?','Откройте раздел «Аренда», выберите автомобиль и даты. Нажмите «Рассчитать стоимость», проверьте сумму и отправьте заявку. Менеджер согласует наличие автомобиля и условия поездки. Решение появится в разделе «Мои заявки».','faq',true,now()),
('wiki','Где посмотреть мои поездки и суммы?','Раздел «История» показывает даты, стоимость и статус аренд. Во вкладке «Заявки» видны отправленные запросы и ответ менеджера. Дополнительные сведения об аренде можно уточнить через кнопку «Связаться с RPM».','faq',true,now()),
('wiki','Можно ли отменить заявку?','Пока заявка находится на рассмотрении, её можно отменить в разделе «Мои заявки». Если аренда уже подтверждена, свяжитесь с менеджером RPM: условия отмены согласуются отдельно.','faq',true,now()),
('wiki','Как получить следующий уровень?','Суммы завершённых и полностью оплаченных аренд учитываются в прогрессе карты. Оставшаяся сумма показана на главной странице. Пороги, проценты и дополнительные привилегии доступны в разделе «Условия» и при просмотре карт.','faq',true,now()),
('wiki','Как связаться с RPM при ДТП, поломке или другой проблеме?','Используйте кнопку «Связаться с RPM» внизу этого раздела. Сообщите менеджеру автомобиль, место и время происшествия и способ связи с вами. Порядок действий и условия обслуживания уточняйте по договору аренды и у ответственного менеджера.','emergency',true,now());
